"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["16045"],{54661(e){e.exports=JSON.parse('{"id":"FIN-025","slug":"financial-goal","term":"Financial Goal","also_known_as":[],"difficulty":"Beginner","definition":"A financial goal is a specific thing you want to achieve with money, such as building an emergency fund, buying a home, paying off debt or retiring at a certain age.","explanation":["A goal turns vague wishes like \\"I should save more\\" into something you can plan for. A useful financial goal states what you want, how much it will cost and when you want it. \\"Save 15,000 for a home deposit within three years\\" is far easier to act on than \\"save for a house\\".","Once the amount and deadline are clear, the monthly effort becomes obvious. Saving 15,000 in three years means putting aside about 417 a month, before counting any interest earned.","Goals are often grouped by time. Short-term goals, within about a year, might include a holiday or a new laptop. Medium-term goals, one to five years away, might include a car or a wedding. Long-term goals, such as retirement, can be decades away.","The time frame also shapes where the money should be kept. Money needed soon is best kept safe in savings accounts, because there is no time to recover from a fall in value. Money for long-term goals can usually be invested for growth, because there is time to ride out ups and downs."],"note":"","total":1500,"prev":{"slug":"financial-distress","term":"Financial Distress"},"next":{"slug":"financial-inclusion","term":"Financial Inclusion"}}')}}]);